ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ7 見積提出"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "7-1:提案内容に基づく見積書を提示した。")),
                NOT(INCLUDES(CompletionBasis__c, "7-2:見積もりの附帯事項を説明した。")),
                NOT(INCLUDES(CompletionBasis__c, "7-3:見積りに対して担当者に理解をいただいた。"))
            )
        )
    )
)
